def choose_move(observation):
    sx, sy = observation.get("self_position", (0, 0))
    env = observation.get("environment_name", "resource_collection")

    ox, oy = observation.get("opponent_position", (sx, sy))
    grid_width = observation.get("grid_width", 1)
    grid_height = observation.get("grid_height", 1)

    def move_towards(target_x, target_y):
        dx = 0
        dy = 0
        if target_x > sx:
            dx = 1
        elif target_x < sx:
            dx = -1
        if target_y > sy:
            dy = 1
        elif target_y < sy:
            dy = -1
        return [dx, dy]

    # Pursuit-evasion behavior
    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return move_towards(ox, oy)
        else:
            corners = [
                (0, 0),
                (0, grid_height - 1),
                (grid_width - 1, 0),
                (grid_width - 1, grid_height - 1),
            ]
            target = min(corners, key=lambda c: abs(c[0] - ox) + abs(c[1] - oy))
            return move_towards(target[0], target[1])

    # Territory control behavior
    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or \
                  observation.get("opponent_territory") or []
        if not targets:
            return [0, 0]
        best_target = min(targets, key=lambda t: abs(t[0] - sx) + abs(t[1] - sy))
        return move_towards(best_target[0], best_target[1])

    # Resource collection behavior
    resources = observation.get("resources") or []
    if resources:
        best_resource = min(resources, key=lambda t: abs(t[0] - sx) + abs(t[1] - sy))
        return move_towards(best_resource[0], best_resource[1])
    else:
        # No resources, move towards opponent or stay still
        return move_towards(ox, oy)

